import{_ as a}from"./chunks/26c01b321adb77cd693d3070f7af8528.Cmwa54Gr.js";import{_ as s,c as e,a2 as t,o as l}from"./chunks/framework.BnrAgU0Y.js";const b=JSON.parse('{"title":"Simple agent","description":"Simple agent","frontmatter":{"title":"Simple agent","description":"Simple agent","layout":"doc"},"headers":[],"relativePath":"langflow/starter-projects-simple-agent.md","filePath":"langflow/starter-projects-simple-agent.md"}'),p={name:"langflow/starter-projects-simple-agent.md"};function r(i,n,o,c,g,d){return l(),e("div",null,n[0]||(n[0]=[t('<h1 id="simple-agent" tabindex="-1">Simple agent <a class="header-anchor" href="#simple-agent" aria-label="Permalink to &quot;Simple agent&quot;">​</a></h1><p>构建一个 <strong>简单代理（Simple Agent）</strong> 流程，用于代理应用程序，使用 <strong>工具调用代理（Tool-calling agent）</strong> 组件。</p><p>一个 <strong>代理（Agent）</strong> 使用大型语言模型（LLM）作为其“头脑”来选择连接的工具，并完成其任务。</p><p>在此流程中，<strong>工具调用代理</strong> 使用 <strong>Open AI</strong> 的大型语言模型进行推理。该代理选择 <strong>计算器（Calculator）</strong> 工具用于解决简单的数学问题，并选择 <strong>URL</strong> 工具用于在 URL 中搜索内容。</p><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><p>要使用此流程，您需要一个 OpenAI API 密钥。</p><h2 id="打开-langflow-并开始一个新流程" tabindex="-1">打开 Langflow 并开始一个新流程 <a class="header-anchor" href="#打开-langflow-并开始一个新流程" aria-label="Permalink to &quot;打开 Langflow 并开始一个新流程&quot;">​</a></h2><p>点击<strong>新建流程</strong>，然后选择<strong>简单代理</strong>流程。</p><p>这将打开一个启动流程，其中包含使用工具调用代理来运行代理应用程序所需的组件。</p><h2 id="简单代理流程" tabindex="-1">简单代理流程 <a class="header-anchor" href="#简单代理流程" aria-label="Permalink to &quot;简单代理流程&quot;">​</a></h2><p><img src="'+a+`" alt="Starter flow simple agent"></p><p><strong>Simple Agent</strong> 流程由以下组件组成：</p><ul><li><strong>Tool calling agent</strong> 组件使用连接的 LLM（大语言模型）来推理用户的输入，并从连接的工具中选择以完成任务。</li><li><strong>URL</strong> 工具组件搜索 URL 列表以查找内容。</li><li><strong>Calculator</strong> 组件执行基本的算术运算。</li><li><strong>Chat Input</strong> 组件接收用户输入到聊天中。</li><li><strong>Prompt</strong> 组件将用户输入与用户定义的提示相结合。</li><li><strong>Chat Output</strong> 组件将流程的输出输出到聊天中。</li><li><strong>OpenAI</strong> 模型组件将用户输入和提示发送到 OpenAI API 并接收响应。</li></ul><h2 id="运行简单代理流程" tabindex="-1">运行简单代理流程 <a class="header-anchor" href="#运行简单代理流程" aria-label="Permalink to &quot;运行简单代理流程&quot;">​</a></h2><ol><li><p>将您的凭据添加到 Open AI 组件中。</p></li><li><p>点击 <strong>Playground</strong> 以开始一个聊天会话。</p></li><li><p>要确认工具已连接，询问代理，<code>What tools are available to you?</code>（你有什么工具可用？） 回答类似以下内容：</p></li></ol><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I have access to the following tools:</span></span>
<span class="line"><span>Calculator: 进行基本的算术运算。</span></span>
<span class="line"><span>fetch_content: 从指定的URL加载并检索数据。</span></span>
<span class="line"><span>fetch_content_text: 从指定的URL加载并检索文本数据。</span></span>
<span class="line"><span>as_dataframe: 从指定的URL以结构化格式（数据帧）加载和检索数据。</span></span>
<span class="line"><span>get_current_date: 返回所选时区的当前日期和时间。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><ol start="4"><li>问代理人一个问题。例如，要求它使用您最喜欢的规则集创建一个桌面角色。 代理将告诉您何时使用 <code>URL-fetch_content_text</code> 工具搜索规则信息，以及何时使用 <code>CalculatorComponent-evaluate_expression</code> 通过掷骰子生成属性。 最后的输出应类似于此：</li></ol><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Final Attributes</span></span>
<span class="line"><span>  Strength (STR): 10</span></span>
<span class="line"><span>  Constitution (CON): 12</span></span>
<span class="line"><span>  Size (SIZ): 14</span></span>
<span class="line"><span>  Dexterity (DEX): 9</span></span>
<span class="line"><span>  Intelligence (INT): 11</span></span>
<span class="line"><span>  Power (POW): 13</span></span>
<span class="line"><span>  Charisma (CHA): 8</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>现在您的查询已经从<strong>聊天输入</strong>流转到了<strong>聊天输出</strong>，您已经完成了<strong>简单代理</strong>的流程。</p>`,19)]))}const h=s(p,[["render",r]]);export{b as __pageData,h as default};
